UPDATE sys_user
SET password = #{newHash},
    status = CASE WHEN status = 0 THEN 1 ELSE status END,
    must_change_password = FALSE, session_version = session_version + 1,
    version = version + 1, failed_login_count = 0, locked_until = NULL,
    updated_at = #{now}, updated_by = #{id}
WHERE id = #{id} AND password = #{expectedHash}
  AND session_version = #{expectedSessionVersion}
  AND version < 9223372036854775807 AND session_version < 9223372036854775807
  AND status IN (0, 1)
